SELECT COUNT(*)
FROM auto_transfer_schedule
WHERE member_id = #{memberId}
  AND child_id <=> #{childId}
  AND source_account_id = #{sourceAccountId}
  AND destination_account_id = #{destinationAccountId}
  AND amount = #{amount}
  AND frequency = #{frequency}
  AND transfer_day = #{transferDay}
  AND start_date = #{startDate}
  AND end_date <=> #{endDate}
  AND status IN ('ACTIVE', 'PAUSED')

SELECT ats.auto_transfer_schedule_id AS autoTransferScheduleId, ats.financial_goal_id AS financialGoalId, fg.title AS goalTitle, ats.amount, ats.frequency, ats.transfer_day AS transferDay, ats.next_transfer_at AS nextTransferAt, ats.last_transfer_status AS lastTransferStatus, ats.last_transferred_at AS lastTransferredAt, ats.status FROM auto_transfer_schedule ats LEFT JOIN financial_goal fg ON fg.financial_goal_id = ats.financial_goal_id WHERE ats.child_id = #{childId}
AND ats.status = #{status}
AND ats.auto_transfer_schedule_id < #{cursorId}
ORDER BY ats.auto_transfer_schedule_id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM auto_transfer_schedule
WHERE auto_transfer_schedule_id != #{scheduleId}
  AND member_id = #{memberId}
  AND child_id <=> #{childId}
  AND source_account_id = #{sourceAccountId}
  AND destination_account_id = #{destinationAccountId}
  AND amount = #{amount}
  AND frequency = #{frequency}
  AND transfer_day = #{transferDay}
  AND start_date = #{startDate}
  AND end_date <=> #{endDate}
  AND status IN ('ACTIVE', 'PAUSED')

